function openKnowledgeCategory(cat,navEl){v4ActiveCategory=cat;v4GlobalSearch=false;switchSection('knowledge',navEl);renderKnowledge();document.getElementById('knowledgeDetail').hidden=true;document.getElementById('knowledgeGrid').style.display='grid';}
function renderKnowledge(){const cat=V4_CATEGORIES[v4ActiveCategory]||V4_CATEGORIES.regulasi;const heading=document.getElementById('knowledgeHeading');if(!heading)return;heading.textContent=v4GlobalSearch?'Hasil Pencarian Seluruh Pengetahuan':cat.title;document.getElementById('knowledgeIntro').textContent=v4GlobalSearch?'Hasil pencarian dari lima bidang pengetahuan yang tersimpan di perangkat.':cat.intro;const q=(document.getElementById('knowledgeSearch').value||'').trim().toLocaleLowerCase('id');const sort=document.getElementById('knowledgeSort').value;let rows=V4_ARTICLES.filter(a=>(v4GlobalSearch||a.cat===v4ActiveCategory) && (!q || (a.title+' '+a.summary+' '+a.body+' '+a.ref).toLocaleLowerCase('id').includes(q)));rows.sort((a,b)=>sort==='type'?a.type.localeCompare(b.type,'id'):a.title.localeCompare(b.title,'id'));document.getElementById('knowledgeCount').textContent=rows.length+' materi tersedia';const grid=document.getElementById('knowledgeGrid');grid.innerHTML='';if(!rows.length){grid.innerHTML='<div class="knowledge-empty">Tidak ada materi yang cocok. Coba kata kunci lain.</div>';return;}rows.forEach((a,i)=>{const card=document.createElement('article');card.className='knowledge-card';const top=document.createElement('div');top.className='knowledge-card-top';const tag=document.createElement('span');tag.className='knowledge-type';tag.textContent=a.type;const num=document.createElement('span');num.className='knowledge-number';num.textContent=String(i+1).padStart(2,'0');top.append(tag,num);const h=document.createElement('h4');h.textContent=a.title;const p=document.createElement('p');p.textContent=a.summary;const b=document.createElement('button');b.type='button';b.textContent='Baca materi →';b.addEventListener('click',()=>showKnowledgeArticle(a));card.append(top,h,p,b);grid.append(card);});}
function showKnowledgeArticle(a){const d=document.getElementById('knowledgeDetail');d.hidden=false;d.innerHTML='';const back=document.createElement('button');back.className='article-back';back.textContent='← Kembali ke daftar';back.onclick=()=>{d.hidden=true;document.getElementById('knowledgeGrid').style.display='grid';};const tag=document.createElement('div');tag.className='knowledge-type';tag.style.display='inline-block';tag.style.marginTop='18px';tag.textContent=a.type;const h=document.createElement('h3');h.textContent=a.title;const summary=document.createElement('p');summary.className='article-summary';summary.textContent=a.summary;const body=document.createElement('div');body.className='article-body';body.innerHTML=a.body;const source=document.createElement('div');source.className='article-source';const strong=document.createElement('strong');strong.textContent='Rujukan: ';source.append(strong,document.createTextNode(a.ref||'Rujukan kitab/dokumen perlu dilengkapi menurut edisi yang digunakan.'));if(a.url){source.append(document.createElement('br'));const link=document.createElement('a');link.href=a.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Sumber resmi / dokumen rujukan (perlu internet untuk membuka)';source.append(link);}d.append(back,tag,h,summary,body,source);document.getElementById('knowledgeGrid').style.display='none';d.scrollIntoView({behavior:'smooth',block:'start'});}
function clearKnowledgeSearch(){document.getElementById('knowledgeSearch').value='';renderKnowledge();}
